// Some portions generated by Claude
// Renders every <section class="board"> in mockups.html to mockups/<id>.png.
// Run from the repository root:
//     node design/workbench-app-shell-plan-20260930/render-mockups.cjs
// Requires the Playwright install under e2e/node_modules (cd e2e && npm ci).
const path = require('node:path');
const fs = require('node:fs');
const { chromium } = require(path.resolve(__dirname, '../../e2e/node_modules/playwright'));

(async () => {
	const outDir = path.join(__dirname, 'mockups');
	fs.mkdirSync(outDir, { recursive: true });
	const browser = await chromium.launch();
	const page = await browser.newPage({ viewport: { width: 1600, height: 1200 }, deviceScaleFactor: 1 });
	await page.goto('file://' + path.join(__dirname, 'mockups.html'));
	await page.waitForLoadState('networkidle');
	const ids = await page.$$eval('section.board[id]', nodes => nodes.map(node => node.id));
	for (const id of ids) {
		const file = path.join(outDir, id + '.png');
		await page.locator(`section[id="${id}"]`).screenshot({ path: file });
		console.log('rendered', path.relative(process.cwd(), file));
	}
	await browser.close();
})();
